{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "MMV367, a structurally related azole-containing oral drug, has an estimated human bioavailability of 90%, directly supporting F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Suvorexant, a lipophilic oral drug with a piperazine and heteroaromatic core, has an absolute human bioavailability of 82% under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fluconazole, a triazole antifungal, has an absolute oral bioavailability of 94% in healthy volunteers, supporting high bioavailability for the azole antifungal class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Voriconazole, a triazole antifungal with a fluorophenyl/triazole motif, has a mean absolute oral bioavailability of ~96% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ketoconazole, the closest structural analog with a dichlorophenyl-dioxolane-piperazine azole scaffold, has a mean oral bioavailability of ~75% in healthy volunteers after 200 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Urapidil, a piperazine-containing oral drug, has an absolute bioavailability of 72% relative to IV in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ziprasidone, a lipophilic piperazine drug, has an absolute oral bioavailability of 60% in the fed state, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Fenofibrate, a poorly soluble lipophilic drug, has an absolute bioavailability of ~69% in humans, indicating that solubility limitations do not necessarily reduce F below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an azole antifungal (itraconazole-like) with a dichlorophenyl-dioxolane-triazole-piperazine-triazolone scaffold. The closest azole antifungal analogs—ketoconazole, fluconazole, voriconazole—show human oral bioavailability values of 75-96%, and other high-transfer lipophilic/piperazine oral drugs show 60-90%. Even the lowest quantitative analog values are well above 20%. Therefore F>=20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is included in the supplied evidence; prediction relies on transferable analogs.",
    "Some analogs (ketoconazole, fenofibrate, ziprasidone) show formulation/food-dependent or variable bioavailability, but all reported quantitative values remain above the 20% threshold.",
    "One qualitative low-bioavailability report for ketoconazole is not threshold-specific and is outweighed by multiple quantitative high measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

